function stringify(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(stringify).join(' ');
  if (value && typeof value === 'object') return Object.values(value).map(stringify).join(' ');
  return '';
}

module.exports = function applyFillHighlights(points) {
  (points || []).forEach((point) => {
    const answers = FILL_HIGHLIGHTS[point.id] || [];
    if (!answers.length) return;
    point.fillHighlights = answers;
    point.tabs = (point.tabs || []).map((tab) => ({
      ...tab,
      blocks: (tab.blocks || []).map((block) => {
        const text = stringify(block);
        const matched = answers.filter((answer) => text.includes(answer));
        return { ...block, highlights: Array.from(new Set([...(block.highlights || []), ...matched])) };
      }),
    }));
  });
};

module.exports.FILL_HIGHLIGHTS = FILL_HIGHLIGHTS;
